// procedural world sketch for: Alien Environment Research Generator
let s = 63401919;
const rnd = () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296;
const W = 18, H = 10; let land = 0, water = 0;
for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { if (rnd() < 0.4) land++; else water++; }
console.log(JSON.stringify({ width: W, height: H, landCells: land, waterCells: water,
  landFraction: +(land / (W * H)).toFixed(3), seed: 63401919 }));

